sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {


    try {
        var updateCase = new GlideRecord("x_hsb11_mss_taskiz_mss_taskize_case");
        updateCase.get(current.sys_id);
        if ((current.assigned_to.changes() && current.assigned_to == "")) {

            updateCase.state = 1; //set To New When Assignment Group Cleared
        } else if (current.assigned_to.changes() && current.assigned_to != "") {

            updateCase.state = 2; //work in Progress when assigned to a group
        } else {

            var auditRec = new GlideRecord("sys_audit");
            auditRec.addEncodedQuery("tablenameSTARTSWITHx_hsb11_mss_taskiz_mss_taskize_case^documentkeySTARTSWITH" + current.sys_id + '^fieldname=comments');
            auditRec.orderByDesc('sys_created_on');
            auditRec.setLimit(1);
            auditRec.query();
            if (auditRec.next()) {
                var fieldName = auditRec.fieldname.toString();
                var currentValue = auditRec.newvalue;
                var taskizeCase = auditRec.documentkey;
                var userID = auditRec.user;
                //to set in Awaiting Info when an comment is added by an internal user 
                if ((fieldName == 'comments') && (userID.indexOf('system') == -1) && (currentValue != '') && current.assigned_to != "") {

                    updateCase.state = 18; //Awaiting Info
                }
                //to set in Work in Progress when a comment is added by integration system user
                else if ((fieldName == 'comments') && (userID.indexOf('system') > -1) && (currentValue != '') && current.assigned_to != "") {

                    updateCase.state = 2; //Work in Progress
                }
            }

        }
        updateCase.update();
    } catch (ex) {
        gs.info('Error from Business Rule - MSS Taskize Case State Changes ' + ex);
    }

})(current, previous);
